#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int *grow(int *a, int old_n, int new_n) {
    int *b = realloc(a, sizeof(int) * new_n);
    for (int i = old_n; i < new_n; i++) {
        b[i] = 0;
    }
    return b;
}

int main() {
    int *a = malloc(sizeof(int) * 2);
    a[0] = 7;
