#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *copy_str(char *s) {
    char *c = malloc(strlen(s) + 1);
    strcpy(c, s);
    return c;
}

int main() {
    char name[] = "tanaka";
    char *c = copy_str(name);
    c[0] = 'T';
    printf("%s %s\n", name, c);
    free(c);
    return 0;
}

