#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int *alloc_scores(int n) {
    if (n <= 0) {
        return NULL;
    }
    int *a = malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        a[i] = 0;
    }
    return a;
}

int main() {
    int *a = alloc_scores(3);
    printf("%d %d\n", a[0], alloc_scores(0) == NULL);
    free(a);
    return 0;
}
